// Functional local UI. Authentication, membership, media and posts are authorized by the server.
const app = document.getElementById('app');
const nav = document.getElementById('account-nav');
const alertBox = document.getElementById('app-alert');
const dialog = document.getElementById('app-dialog');
const dialogBody = document.getElementById('app-dialog-content');
const state = {user:null,hub:null,memberships:[],requests:[],inbox:{pendingRequests:0},notifications:{},billingConfigs:{},checkoutKeys:{},checkoutGeneration:0,runtime:{known:false,environment:'unknown',emailMode:'unknown',billingEnabled:false,testMode:true,bodyBytes:4*1024*1024},email:'',next:'#home',photos:{},selection:0,epoch:0,sessionGeneration:0,modalGeneration:0,authVerifyPending:false,authVerifyEmail:'',authMode:'signup',join:{name:'',email:'',agreed:false},cameraGeneration:0,registrationPending:false,acquisitionSlug:'',shares:{},qrSeen:{},planChoices:{},annualDiscount:25,chatDrafts:{},chatContext:null,chatPending:new Set(),accessTimer:null,communityCaption:''};
let returnFocus,toastTimer,ready=false,cameraStream=null;
const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow = '<span class="arrow-icon" aria-hidden="true"></span>';
const lock = '<svg class="lock" viewBox="0 0 20 20" aria-hidden="true"><rect x="4" y="8" width="12" height="10" rx="2"/><path d="M6.5 8V5a3.5 3.5 0 0 1 7 0v3M10 12v3"/></svg>';
const hubLink = slug => '#hub/'+encodeURIComponent(slug);
const feedLink = slug => '#feed/'+encodeURIComponent(slug);
const manageLink = slug => '#manage/'+encodeURIComponent(slug);
const complete = () => !!(state.user?.name&&state.user?.photoUrl);
const registrationRoute=()=>state.user?.verified&&state.join.name&&state.join.agreed&&state.join.email===state.user.email?'#join-photo':'#signup';
const dateLabel = value => {const d=new Date(value);return Number.isNaN(d.getTime())?'':d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})};
const dateTimeLabel=value=>{const d=new Date(value);return Number.isNaN(d.getTime())?'':d.toLocaleString(undefined,{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'})};
function photoUrl(value){
 if(typeof value!=='string'||!value.startsWith('/api/wildhub?'))return '';
 try{const u=new URL(value,location.origin);return u.origin===location.origin&&u.pathname==='/api/wildhub'&&u.searchParams.get('action')==='media'?value:''}catch{return ''}
}
const avatar = (value,name,extra='') => photoUrl(value)?`<img class="portrait ${extra}" src="${esc(photoUrl(value))}" alt="${esc(name||'Profile photo')}" width="80" height="80">`:'<span class="profile-placeholder" aria-label="No profile photo">+</span>';
function notify(message){clearTimeout(toastTimer);const el=document.getElementById('app-status');el.textContent=message;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),4500)}
function showError(error){alertBox.textContent=error?.message||'That didn’t work. Try again.'}
function clearError(){alertBox.textContent=''}
function redactProtectedError(error){if(![401,402,403,404].includes(error?.status)||!/^#(?:feed|chat|membership)\//.test(location.hash))return false;clearTimeout(state.accessTimer);state.chatContext=null;app.innerHTML=`<section class="server-error"><h1>This space is closed.</h1><p>${esc(error.message)}</p><p class="small-note">Current approval and membership access are required. Refresh to check again.</p><div class="button-row"><button class="button" data-action="refresh">Check access</button><a class="button secondary" href="#home">Go home</a></div></section>`;return true}
function scheduleAccessExpiry(access,ticket){clearTimeout(state.accessTimer);if(access.source==='owner'||!access.allowed)return;const cutoff=Date.parse(access.source==='trial'?access.trialEndsAt:access.paidUntil);if(!Number.isFinite(cutoff))return;const remaining=cutoff-Date.now(),delay=remaining>0?remaining+25:60000;state.accessTimer=setTimeout(()=>{if(ticket===state.epoch)render()},Math.min(delay,2147483647));}
const providerMail=()=>state.runtime.emailMode==='provider';
const environmentLabel=()=>state.runtime.environment==='isolated-test'?'Isolated test':'Local test';
function registrationNotice(){return providerMail()?'Isolated test only: sign-in and notification emails go only to permitted test recipients. Email codes confirm access to an address, not identity. This reuses the Duh Wild registration flow; no new public-service terms are being accepted here.':'Local test only: no real email is sent. The code appears in the server terminal. This reuses the Duh Wild registration flow; no new public-service terms are being accepted here.'}
function runtimeUnavailable(){return `<section class="server-error"><h1>Test settings are unavailable.</h1><p>We couldn’t confirm this server’s email and payment settings. Registration and changes are paused until the connection is restored.</p><button class="button" data-action="refresh">Retry connection</button></section>`}
async function loadRuntime(){
 state.runtime.known=false;
 try{const response=await fetch('/api/wildhub-config',{method:'GET',credentials:'same-origin',cache:'no-store'}),config=await response.json();if(!response.ok||config.ok!==true||!['local','isolated-test'].includes(config.environment)||config.testMode!==true||!['provider','simulated'].includes(config.emailMode)||config.environment==='local'&&config.emailMode!=='simulated')throw Error('Invalid test configuration');state.runtime={known:true,environment:config.environment,emailMode:config.emailMode,billingEnabled:config.billingEnabled===true,testMode:true,bodyBytes:Number.isSafeInteger(config.bodyBytes)&&config.bodyBytes>=1024&&config.bodyBytes<=7*1024*1024?config.bodyBytes:4*1024*1024};}
 catch{state.runtime={known:false,environment:'unknown',emailMode:'unknown',billingEnabled:false,testMode:true,bodyBytes:4*1024*1024};const bar=document.querySelector('.review-bar');bar.innerHTML='<span><i></i> TEST CONFIGURATION UNAVAILABLE</span><span>Registration and changes are paused.</span>';throw Error('Couldn’t confirm the test server settings. Retry the connection.')}
 const bar=document.querySelector('.review-bar');bar.innerHTML=`<span><i></i> ${environmentLabel().toUpperCase()} BUILD</span><span>${providerMail()?'Permitted test emails only.':'Simulated test inboxes.'} Sandbox payments only when enabled.</span>`;const privacy=document.querySelector('.site-footer a[href="#privacy"]');if(privacy)privacy.textContent=environmentLabel()+' privacy';
}
async function api(action,data,query={}){
 if(data!==undefined&&!state.runtime.known)throw Error('Test settings are unavailable. Retry the connection before making changes.');
 const params=new URLSearchParams({action,...Object.fromEntries(Object.entries(query).filter(([,v])=>v!==undefined&&v!==null))});
 const body=data===undefined?undefined:JSON.stringify(data);if(body&&new Blob([body]).size>state.runtime.bodyBytes)throw Error('This upload is too large for the test server. Choose a smaller photo.');let response;
 try{response=await fetch('/api/wildhub?'+params,{method:data===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:data===undefined?{}:{'content-type':'application/json'},...(data===undefined?{}:{body})})}catch{throw Object.assign(Error('Couldn’t reach the test server. Your form is still here; try again.'),{code:'network'})}
 let result;try{result=await response.json()}catch{throw Error('The test server returned an unreadable response.')}
 if(!response.ok||result.ok===false){const detail=result.error;throw Object.assign(Error(typeof detail==='string'?detail:detail?.message||'This request is unavailable.'),{code:detail?.code||'request_failed',status:response.status})}
 return result;
}
async function billingApi(action,data,query={}){
 if(data!==undefined&&!state.runtime.known)throw Error('Test settings are unavailable. Retry the connection before checkout.');
 const params=new URLSearchParams({action,...query});let response;
 try{response=await fetch('/api/wildhub-billing?'+params,{method:data===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:data===undefined?{}:{'content-type':'application/json'},...(data===undefined?{}:{body:JSON.stringify(data)})})}catch{throw Error('Test checkout is unavailable. Your community access has not changed.')}
 let result;try{result=await response.json()}catch{throw Error('Test checkout returned an unreadable response.')}
 if(!response.ok||result.ok===false){const error=result.error;throw Object.assign(Error(typeof error==='string'?error:error?.message||'Test checkout is unavailable.'),{status:response.status,code:error?.code})}return result;
}
function safeCheckoutUrl(value){try{const u=new URL(value);return u.protocol==='https:'&&u.hostname==='checkout.stripe.com'&&!u.port&&!u.username&&!u.password?u.href:''}catch{return ''}}
function validatedBilling(config){if(config?.enabled!==true||config?.testMode!==true||config?.canCheckout!==true||!state.runtime.billingEnabled)return {enabled:false,testMode:false,membership:[],support:[]};const valid=(p,kind)=>p&&typeof p.planKey==='string'&&/^[a-z][a-z0-9_-]{0,49}$/.test(p.planKey)&&typeof p.label==='string'&&/^[a-z]{3}$/i.test(p.currency)&&Number.isSafeInteger(p.unitAmount)&&p.unitAmount>0&&(kind==='support'||['day:1','month:1','month:3','year:1'].includes(p.interval+':'+p.intervalCount));return {enabled:true,testMode:true,membership:(Array.isArray(config.membership)?config.membership:[]).filter(p=>valid(p,'membership')),support:(Array.isArray(config.support)?config.support:[]).filter(p=>valid(p,'support'))}}
async function billingConfig(hubId){const [config,status]=await Promise.all([billingApi('config',undefined,{hubId}).catch(()=>null),billingApi('status',undefined,{hubId}).catch(()=>null)]);return {...validatedBilling(config),status:status?.enabled===true&&status.testMode===true?status:null}}
async function refreshMe(){const generation=state.sessionGeneration;const result=await api('me');if(generation!==state.sessionGeneration)return result;state.user=result.user;state.hub=result.hub;state.memberships=result.memberships||[];state.requests=result.requests||[];state.inbox=result.inbox||{pendingRequests:0};syncNotifications();renderNav();return result}
function renderNav(){if(state.user&&!complete()){nav.innerHTML='<button class="nav-cta" data-action="logout">Cancel registration</button>';return}nav.innerHTML=state.user?`${state.hub?`<a href="${manageLink(state.hub.slug)}">Your hub</a>`:'<a href="#create">Create a hub</a>'}<a href="#dashboard">My communities</a><a href="#my-qr">My QR</a><a class="account-line" href="#profile">${state.user.photoUrl?avatar(state.user.photoUrl,'Your profile'):''}<span class="profile-label">Your profile</span></a><button class="nav-cta" data-action="logout">Sign out</button>`:'<a href="#signin">Sign in</a><a class="nav-cta" href="#signup">Make your page '+arrow+'</a>'}
function navigate(hash){if(location.hash===hash)render();else location.hash=hash}
function signedIn(target){if(state.user)return true;state.next=target||location.hash||'#home';navigate('#signin');return false}
function profileReady(target){if(!signedIn(target))return false;if(complete())return true;state.next=target||location.hash;navigate(registrationRoute());return false}
function modal(title,body){if(!dialog.open)returnFocus=document.activeElement;state.modalGeneration++;dialogBody.innerHTML=`<div class="modal-content"><div class="modal-top"><h2 id="dialog-title">${esc(title)}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div>${body}</div>`;if(!dialog.open)dialog.showModal();document.body.style.overflow='hidden';dialog.querySelector('input,button')?.focus()}
function closeModal(){state.modalGeneration++;state.selection++;delete state.photos.post;dialog.close();dialogBody.replaceChildren();document.body.style.overflow='';if(returnFocus?.isConnected)returnFocus.focus()}
const hubAddressHelp='Short address: use 3–40 letters (a–z), numbers or hyphens, with a letter or number at each end and no spaces. Example: test-hub.';
function hubAddressError(form,message=''){const input=form.elements.namedItem('slug'),error=form.querySelector('#hub-slug-error');input.setCustomValidity(message);if(message)input.setAttribute('aria-invalid','true');else input.removeAttribute('aria-invalid');error.textContent=message;error.hidden=!message}
function formError(form,error){if(form.id==='hub-form'&&['invalid_slug','slug_taken'].includes(error.code)){hubAddressError(form,error.code==='slug_taken'?'Short address: this link is already taken. Choose another address, such as test-hub3.':hubAddressHelp);return}const target=form.querySelector('.form-error:not(#hub-slug-error)');if(target)target.textContent=error.message||String(error);else showError(error)}
async function mutate(form,work){
 if(form.dataset.busy)return;
 form.dataset.busy='true';form.setAttribute('aria-busy','true');
 const controls=[...form.querySelectorAll('input,textarea,select,button[type=submit]')].map(el=>({el,disabled:el.disabled}));controls.forEach(({el})=>el.disabled=true);
 form.querySelector('.form-error:not(#hub-slug-error)')?.replaceChildren();
 const hash=location.hash,sessionGeneration=state.sessionGeneration,modalGeneration=state.modalGeneration,inDialog=dialog.contains(form);
 try{await work(()=>state.sessionGeneration===sessionGeneration&&location.hash===hash&&form.isConnected&&(!inDialog||dialog.open&&state.modalGeneration===modalGeneration),()=>state.sessionGeneration===sessionGeneration)}catch(error){if(state.sessionGeneration===sessionGeneration&&location.hash===hash&&form.isConnected){if(!redactProtectedError(error))formError(form,error.status===409&&['remove-form','leave-form'].includes(form.id)?Error('This membership changed. Close this dialog and refresh before deciding again.'):error)}}
 finally{delete form.dataset.busy;form.removeAttribute('aria-busy');controls.forEach(({el,disabled})=>el.disabled=disabled);if(form.id==='hub-form'&&form.isConnected)form.querySelector('[aria-invalid="true"]')?.focus()}
}
function agreeBox(id,on){return `<label class="agree"><input type="checkbox" name="agreed" id="${id}" ${on?'checked':''}><span>I’m 18 or older and agree to the <a href="https://chempatible.com/terms" target="_blank" rel="noreferrer">Terms</a> and <a href="https://chempatible.com/privacy" target="_blank" rel="noreferrer">Privacy Policy</a>.</span></label>`}
function authView(mode){
 if(state.authVerifyPending)return `<section class="box joinCard instantEntry"><h2>Checking your code…</h2><p>Finish the sign-in for ${esc(state.authVerifyEmail)} before switching email addresses.</p></section>`;
 if(state.user&&complete()){navigate(state.next||'#home');return ''}
 const joining=state.authMode==='signup';
 const notice=`<p class="registration-test-note">${registrationNotice()}</p>`;
 if(mode==='verify')return `<section class="box joinCard instantEntry"><form class="app-form registration-form" id="verify-form"><div class="eyebrow">${joining?'1 · CHECK YOUR EMAIL':'WELCOME BACK'}</div><h2>Enter your code.</h2><p>${providerMail()?'Check your email for a six digit code for':'The local test inbox has a six digit code for'} <b>${esc(state.email)}</b>. It’s at the start of the test email’s subject line.</p><input class="joinInput" id="signinCode" name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" aria-label="Six digit code" placeholder="000000" required><button type="submit" class="button nextButton">${joining?'CONTINUE →':'SIGN IN →'}</button><p id="joinError" class="error form-error" role="alert"></p><p class="small">Need another code? <button type="button" class="link" data-action="resend">Resend code</button></p><a class="link" href="${joining?'#signup':'#signin'}">Use a different email</a>${notice}</form></section>`;
 if(mode==='signin')return `<section class="box joinCard instantEntry"><form class="app-form registration-form" id="signin-form"><div class="eyebrow">WELCOME BACK</div><h2>Sign in.</h2><p>We’ll send a six digit code to the address on your page.</p><input class="joinInput" id="signinEmail" name="email" type="email" aria-label="Your email" autocomplete="email" placeholder="Your email" value="${esc(state.email)}" required><button type="submit" class="button nextButton">SEND CODE →</button><p id="joinError" class="error form-error" role="alert"></p><a class="link" href="#signup">← New here? Start your page</a>${notice}</form></section>`;
 return `<section class="box joinCard instantEntry"><form class="app-form registration-form" id="signup-form"><h1>Make your page.</h1><p class="entryNote">Start with your name and email. Your email stays private.</p><input class="joinInput" id="joinName" name="name" aria-label="Your name" autocomplete="given-name" maxlength="50" placeholder="Your first name" value="${esc(state.join.name)}" required><input class="joinInput" id="joinContact" name="email" type="email" aria-label="Your email" autocomplete="email" placeholder="Your email" value="${esc(state.join.email||state.email)}" required>${agreeBox('joinAgree',state.join.agreed)}<button type="submit" class="button nextButton">CONTINUE →</button><p id="joinError" class="error form-error" role="alert"></p><a class="link" href="#signin">Already have a page? Sign in →</a>${notice}</form></section>`;
}
function registrationPhotoView(){const saving=state.registrationPending&&state.registrationPending.generation===state.sessionGeneration;return `<section class="box joinCard instantEntry"><div class="eyebrow">2 · YOUR PICTURE</div><h2>Add your picture.</h2><p>Let your friend recognize you.</p><div class="photoActions"><button type="button" class="button alt" data-action="camera" data-registration-control ${saving?'disabled':''}>CAMERA</button><label class="button light photoPick">CHOOSE FILE PHOTO<input id="memberPhoto" class="photoFileInput" type="file" accept="image/*" data-photo="registration" data-registration-control ${saving?'disabled':''}></label></div><video id="cameraPreview" class="cameraPreview" autoplay muted playsinline hidden></video><canvas id="cameraCanvas" hidden></canvas><button id="captureBtn" type="button" class="button captureButton" data-action="capture" data-registration-control ${saving?'disabled':''} hidden>SMILE &amp; CAPTURE</button><p id="joinError" class="error form-error" role="alert">${saving?'Saving your picture…':''}</p><a class="link" href="#signup">← Back to details</a><p class="registration-test-note">Choosing or capturing your photo completes the same registration sequence. Your own shareable QR comes next, followed by your circle introduction. Membership choices open after host approval. Uploaded images stay in this isolated test database.</p></section>`}
function stopCamera(){state.cameraGeneration++;cameraStream?.getTracks().forEach(track=>track.stop());cameraStream=null;const video=document.getElementById('cameraPreview');if(video){video.srcObject=null;video.hidden=true}const capture=document.getElementById('captureBtn');if(capture)capture.hidden=true}
async function openRegistrationCamera(){
 const error=document.getElementById('joinError');error.textContent='';
 if(!navigator.mediaDevices?.getUserMedia){error.textContent='No camera is available in this browser. Use CHOOSE FILE PHOTO.';return}
 stopCamera();const generation=state.cameraGeneration,route=location.hash;
 try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});if(generation!==state.cameraGeneration||route!==location.hash){stream.getTracks().forEach(track=>track.stop());return}cameraStream=stream;const video=document.getElementById('cameraPreview');if(!video){stopCamera();return}video.srcObject=stream;video.hidden=false;document.getElementById('captureBtn').hidden=false;await video.play()}
 catch(e){if(generation!==state.cameraGeneration||route!==location.hash)return;stopCamera();error.textContent=e.name==='NotAllowedError'?'Camera access was blocked. Allow camera access in your browser, or use CHOOSE FILE PHOTO.':'No camera was found. Use CHOOSE FILE PHOTO.'}
}
async function captureRegistrationPhoto(){const video=document.getElementById('cameraPreview');if(!video?.videoWidth){document.getElementById('joinError').textContent='Wait for the camera, then capture your picture.';return}const canvas=document.getElementById('cameraCanvas'),side=Math.min(video.videoWidth,video.videoHeight);canvas.width=canvas.height=320;canvas.getContext('2d').drawImage(video,(video.videoWidth-side)/2,(video.videoHeight-side)/2,side,side,0,0,320,320);const picture=canvas.toDataURL('image/jpeg',.78);stopCamera();await finishRegistration(picture)}
async function finishRegistration(picture){
 if(state.registrationPending&&state.registrationPending.generation===state.sessionGeneration)return;
 const error=document.getElementById('joinError'),route=location.hash,generation=state.sessionGeneration,actorId=state.user?.id,submittedEmail=state.join.email,viewEpoch=state.epoch;
 const ownsIdentity=()=>generation===state.sessionGeneration&&actorId===state.user?.id&&submittedEmail===state.join.email;
 const ownsView=()=>ownsIdentity()&&route===location.hash&&viewEpoch===state.epoch;
 if(!state.join.name||!state.join.agreed||state.join.email!==state.user?.email){if(error)error.textContent='Complete your details and email confirmation to continue.';return}
 const operation={generation};state.registrationPending=operation;const controls=[...app.querySelectorAll('button,input')];controls.forEach(el=>el.disabled=true);if(error)error.textContent='Saving your picture…';
 try{await api('profile_save',{name:state.join.name,photoDataUrl:picture,agreed:true});if(!ownsIdentity())return false;await refreshMe();if(!ownsIdentity())return false;if(ownsView()){navigate(state.next.startsWith('#invite/')?state.next:state.acquisitionSlug?'#my-qr/'+encodeURIComponent(state.acquisitionSlug):'#my-qr');notify('Your page is ready. Your shareable QR comes next.')}return true}
 catch(e){if(ownsView()&&error?.isConnected)error.textContent=e.message;return false}
 finally{if(state.registrationPending===operation){state.registrationPending=false;if(ownsIdentity()&&/^#join-photo(?:\/|$)/.test(location.hash)){app.querySelectorAll('[data-registration-control]').forEach(el=>el.disabled=false);const currentError=document.getElementById('joinError');if(currentError?.textContent==='Saving your picture…')currentError.textContent=''}}controls.forEach(el=>el.disabled=false)}
}
function profileView(){return `<section class="auth-shell"><p class="eyebrow">YOUR NAME. YOUR PICTURE.</p><h1>Be a familiar face.</h1><p>Your name and photo introduce you to hosts and approved circles. Your email is used for sign-in and invitations.</p><form class="app-form" id="profile-form"><label>Your name<input name="name" maxlength="50" value="${esc(state.user.name)}" autocomplete="given-name" required></label><label>Your picture<input type="file" name="photo" data-photo="profile" accept="image/jpeg,image/png,image/webp" ${state.user.photoUrl?'':'required'}></label><div id="profile-preview">${state.photos.profile?`<img class="photo-sample" src="${esc(state.photos.profile)}" alt="Selected profile photo">`:avatar(state.user.photoUrl,'Your current profile','photo-sample')}</div><p class="field-note">Choose JPEG, PNG or WebP, up to 5 MiB. Your photo is cropped and the server checks and re-encodes it.</p><label class="checkbox-label"><input type="checkbox" name="agreed" required><span>I confirm I’m 18 or older and understand that hosts reviewing my request and people in my approved circles can see my name and photo.</span></label><p class="field-note">Publishing a host page is a separate choice. Changing this photo does not silently change a photo you already published.</p><p class="form-error" role="alert"></p><div class="button-row"><button type="submit" class="button">Save my profile ${arrow}</button><a class="button secondary" href="#home">Cancel</a></div></form></section>`}
function hubForm(){const hub=state.hub;return `<section class="auth-shell"><p class="eyebrow">YOUR OWN LITTLE CORNER</p><h1>${hub?'Make it your own.':'Create your hub.'}</h1><p>A public introduction, with a private circle behind it.</p><form class="app-form" id="hub-form" novalidate><label>Hub name<input name="name" maxlength="50" placeholder="My little corner" value="${esc(hub?.name)}" aria-describedby="hub-name-help" required></label><p class="field-note" id="hub-name-help">The name people see. Spaces are welcome, like “test hub”.</p><label>Short address<input name="slug" pattern="[a-z0-9][a-z0-9\\-]{1,38}[a-z0-9]" minlength="3" maxlength="40" placeholder="test-hub" value="${esc(hub?.slug)}" autocapitalize="none" spellcheck="false" aria-describedby="hub-slug-help hub-slug-error" title="${hubAddressHelp}" required></label><p class="field-note" id="hub-slug-help">Your hub link, e.g. test-hub. Use 3–40 letters (a–z), numbers or hyphens, with a letter or number at each end. No spaces; uppercase becomes lowercase. Do not include private information.</p><p class="form-error" id="hub-slug-error" role="alert" hidden></p><label>A little about this space<textarea name="about" maxlength="500" placeholder="What will you share, and who is this space for?">${esc(hub?.about)}</textarea></label><label class="checkbox-label"><input type="checkbox" name="published" ${hub?.published?'checked':''}><span>Publish my front-door page so people can find it and request to join.</span></label><label class="checkbox-label"><input type="checkbox" name="publishConsent"><span>If publishing, I agree to make my current name, profile photo, hub name and introduction publicly visible. Private posts and the member list remain restricted.</span></label><p class="field-note">${state.runtime.environment==='isolated-test'?'Publishing makes this host introduction visible at the isolated test site.':'This local server is not an internet deployment. Publishing here changes only the local test database.'} Uncheck “Publish” to hide your public page.</p><p class="form-error" role="alert"></p><div class="button-row"><button type="submit" class="button">Save my hub ${arrow}</button><a class="button secondary" href="#home">Cancel</a></div></form></section>`}
function latestRequests(){return state.requests.filter((r,index,list)=>list.findIndex(item=>item.hubId===r.hubId)===index)}
function syncNotifications(){for(const request of latestRequests())if(request.notification)state.notifications[request.hubId]=request.notification}
function notificationLabel(notification){const status=notification?.status,simulated=notification?.deliveryMode==='simulated';return status==='accepted'?(simulated?'Test email accepted into the simulated inbox; no real email was sent.':'Email accepted by the provider; inbox delivery is not confirmed.'):status==='queued'?'Email queued in the isolated outbox.':status==='retrying'?'Email is waiting for a retry. Your request status is saved.':status==='suppressed'?'Email was suppressed by the test delivery rules. Your request status is saved.':status==='uncertain'?'Email delivery status is uncertain. Your request status is saved.':status==='failed'?'Email could not be sent. Check the saved status here.':''}
function deliveryNote(hubId){const label=notificationLabel(state.notifications[hubId]);return label?`<p class="delivery-status" role="status">${esc(label)}</p>`:''}
function memberDashboard(){
 const latest=latestRequests(),memberships=state.memberships.filter(m=>m.role!=='owner'&&(m.status==='active'||!latest.some(r=>r.hubId===m.hubId&&r.status==='pending'))),membershipHubs=new Set(memberships.map(m=>m.hubId)),requests=latest.filter(r=>!membershipHubs.has(r.hubId));
 if(!state.user||!memberships.length&&!requests.length)return '';
 return `<section class="member-dashboard" aria-label="Your community status"><div class="community-section-heading"><h2>Your communities</h2><button class="text-link" data-action="refresh">Refresh status</button></div><div class="member-status-grid">${memberships.map(m=>{const active=m.status==='active',access=m.access||{},label=!active?'Access closed':access.source==='expired'?'Approved · Trial ended':access.source==='paid'?'Approved · Paid access':'Approved · Trial available';return `<article class="member-status-card"><span class="status-label">${label}</span><h3>${esc(m.name)}</h3><div class="entitlement-note">${active?accessNote(access):'The host must approve a new admission.'}</div><a class="button secondary" href="${active?'#membership/'+encodeURIComponent(m.slug):hubLink(m.slug)}">${active?'Membership & community':'View request status'} ${arrow}</a></article>`}).join('')}${requests.map(r=>`<article class="member-status-card"><span class="status-label">${r.status==='pending'?'Waiting for the host':r.status==='approved'?'Approved':r.status==='passed'?'Request passed':'Request closed'}</span><h3>${esc(r.hubName)}</h3><p>${r.status==='pending'?'Your introduction is in the host’s request list. No trial or charge has started.':'Check the current host decision before continuing.'}</p><a class="button secondary" href="${hubLink(r.slug)}">View request status ${arrow}</a></article>`).join('')}</div></section>`;
}
function homeView(hubs){return `<section class="app-home">${memberDashboard()}<div class="app-intro-layout"><div class="hero-copy"><p class="eyebrow">MADE FOR YOUR KIND OF PEOPLE</p><h1>Your people.<br>Your space.</h1><p>Your private network. Open to requests. Yours to approve.<br>A simple place to find your people and share a little more.</p><div class="button-row"><a class="button" href="${state.user?(complete()?'#create':registrationRoute()):'#signup'}">${state.hub?'Edit your hub':'Create your circle'} ${arrow}</a>${state.hub?`<a class="button secondary" href="${manageLink(state.hub.slug)}">Manage your hub${state.inbox.pendingRequests?' · '+Number(state.inbox.pendingRequests)+' waiting':''}</a>`:''}</div></div><figure class="app-intro-photo"><img src="/wild-hub/assets/editorial.jpg" alt="Default Wild Hub studio image, with warm light across a wooden table and books"><figcaption>A space for what moves you.</figcaption></figure></div><h2 class="subheading">PUBLIC FRONT DOORS</h2><div class="hub-grid">${hubs.length?hubs.map(h=>`<article class="hub-tile">${avatar(h.photoUrl,h.name)}<h2>${esc(h.name)}</h2><p>${esc(h.about||'A private circle, open to introductions.')}</p><a class="button secondary" href="${hubLink(h.slug)}">Meet the host ${arrow}</a></article>`).join(''):'<div class="empty-state"><h2>The first circle starts with you.</h2><p>No host has published a test page yet.</p></div>'}</div></section>`}
function publicView(result){const {hub,relationship}=result;let gate;
 if(relationship==='owner')gate=`<div class="state-panel"><h3>This is your public page.</h3><a class="button" href="${manageLink(hub.slug)}">Manage your community ${arrow}</a></div>`;
 else if(relationship==='active')gate=`<div class="state-panel"><h3>You’re approved.</h3><p>Your host has approved you. Review your trial, membership and optional support before entering.</p><a class="button" href="#membership/${encodeURIComponent(hub.slug)}">Continue to membership ${arrow}</a></div>`;
 else if(relationship==='pending')gate=`<div class="state-panel"><div class="gate-icon">${lock}</div><h3>Your introduction is waiting.</h3><p>Your request is saved in the host’s dashboard. The host will review your request; an approval reply will point you back here. Your seven-day trial starts only if you’re approved. Nothing is charged before admission.</p>${deliveryNote(hub.id)}<button class="button secondary" data-action="refresh">Check again</button><button class="text-link" data-action="withdraw" data-hub="${esc(hub.id)}">Withdraw my request</button></div>`;
 else if(['passed','removed','blocked'].includes(relationship))gate=`<div class="state-panel"><div class="gate-icon">${lock}</div><h3>This community is closed to you.</h3><p>${relationship==='passed'?'The host passed on this request.':'You don’t have active membership in this community.'}</p><p class="small-note">A QR code, plan selection or payment cannot override the host’s decision.</p></div>`;
 else if(!state.user)gate=`<div class="gate-card"><h3>Start with your profile.</h3><button class="button" data-action="join-signin">Make your page ${arrow}</button></div>`;
 else if(!complete())gate=`<div class="gate-card"><h3>First, your picture.</h3><button class="button" data-action="join-profile">Complete my profile ${arrow}</button></div>`;
 else gate=`<div class="gate-card"><h3>Say hello to ${esc(hub.host?.name||'the host')}.</h3><form class="app-form" id="join-form" data-hub-id="${esc(hub.id)}"><label>Your introduction<textarea name="intro" maxlength="280" placeholder="How do you know the host, or what brings you here?" required></textarea></label><p class="field-note">The host sees your name, picture and introduction. Your email is not shown. First approval starts your seven-day trial. Returning never restarts it; no charge happens before admission.</p><p class="form-error" role="alert"></p><button type="submit" class="button full-width">Request to join ${arrow}</button></form></div>`;
 return `<section class="page-shell thin-host-page"><a class="back-link" href="#home">← Wild Hub</a><header class="thin-host-header"><div class="thin-host-identity">${avatar(hub.photoUrl,hub.host?.name||hub.name,'host-avatar')}<div><p class="eyebrow">${esc(hub.host?.name||'YOUR HOST')} · @${esc(hub.slug)}</p><h1>${esc(hub.name)}</h1></div></div><p class="thin-host-about">${esc(hub.about)}</p></header><div class="thin-host-gate">${gate}</div>${relationship==='active'?`<div class="thin-host-footer"><a class="text-link" href="#membership/${encodeURIComponent(hub.slug)}">Membership and optional support</a></div>`:''}<p class="small-note">The public page is an introduction. Posts, group chat and individual chat require current approved access.</p></section>`;
}
function composerForm(hubId,inline=false){const kind=inline?'communityPost':'post';return `<form class="app-form ${inline?'community-compose':''}" id="${inline?'community-post-form':'post-form'}" data-hub="${esc(hubId)}"><div class="composer-heading"><div><p class="eyebrow">FOR YOUR APPROVED COMMUNITY</p>${inline?'<h2>New post</h2>':''}</div>${avatar(state.user?.photoUrl,state.user?.name)}</div><label class="composer-photo-control">Choose a photo<input type="file" name="photo" data-photo="${kind}" accept="image/jpeg,image/png,image/webp" required></label><div id="${kind}-preview">${state.photos[kind]?`<img class="composition-preview" src="${esc(state.photos[kind])}" alt="Selected post photo">`:''}</div><label class="composer-caption">Caption<textarea name="caption" maxlength="500" placeholder="What would you like to share?">${inline?esc(state.communityCaption):''}</textarea></label><p class="field-note">Only members with current approved access can read this. Previously viewed copies cannot be withdrawn.</p><p class="form-error" role="alert"></p><div class="composer-actions"><button class="button" type="submit">Publish post ${arrow}</button>${inline?'<button class="text-link" type="button" data-action="clear-composer">Clear draft</button>':'<button class="button secondary" type="button" data-action="close">Cancel</button>'}</div></form>`}
function communityPerson(hub,m,owner=false){const eligible=m.access?.allowed!==false;return `<article class="community-person">${eligible&&m.id!==state.user.id?`<a class="community-face" href="#chat/${encodeURIComponent(hub.slug)}/${encodeURIComponent(m.id)}" aria-label="Message ${esc(m.name)}">${avatar(m.photoUrl,m.name)}</a>`:`<span class="community-face" aria-label="${m.id===state.user.id?'Your profile':'Current chat access unavailable'}">${avatar(eligible?m.photoUrl:null,m.name)}</span>`}<span class="community-name">${esc(m.name)}</span><span class="community-role">${m.role==='owner'?'Host':!eligible?'Access ended':m.access?.source==='paid'?'Paid member':'Approved · Trial'}</span>${m.role!=='owner'&&m.access?.trialEndsAt&&m.access?.source==='trial'?`<small class="delivery-status">Ends ${esc(dateTimeLabel(m.access.trialEndsAt))}</small>`:''}${owner&&m.role!=='owner'?`<button class="community-person-actions" data-action="remove-prompt" data-hub="${esc(hub.id)}" data-user="${esc(m.id)}" data-name="${esc(m.name)}" data-revision="${esc(m.access?.membershipRevision||'')}" aria-label="Manage access for ${esc(m.name)}">Manage</button>`:''}</article>`}
function manageView(hub,requests,members){const pending=requests.filter(r=>r.status==='pending');return `<section class="page-shell host-dashboard"><div class="host-topline"><div><p class="eyebrow">${esc(hub.name)}</p><h1>My Community</h1></div><div class="host-toolbar"><button class="button secondary" data-action="host-qr" data-slug="${esc(hub.slug)}" ${hub.published?'':'disabled'}>Host QR ${arrow}</button><button class="button secondary" data-action="invite" data-hub="${esc(hub.id)}">Invite</button><a class="text-link" href="#create">Edit page</a></div></div><p class="host-summary">${pending.length} waiting · ${members.filter(m=>m.role!=='owner'&&m.access?.allowed!==false).length} with current access · First approval starts the trial; each approval queues a reply email.</p>${deliveryNote(hub.id)}<section class="compact-request-strip" aria-label="Pending requests"><div class="strip-heading"><h2>Requests <span>${pending.length}</span></h2><span>First approval starts their seven-day trial</span></div>${pending.length?pending.map(r=>`<article class="compact-request"><div class="request-person">${avatar(r.applicant.photoUrl,r.applicant.name)}<div class="request-copy"><h3>${esc(r.applicant.name)}</h3><details><summary>Read introduction</summary><p>${esc(r.intro)}</p></details><p class="delivery-status">${esc(notificationLabel(r.notification))}</p></div></div><div class="request-decisions"><button class="button" data-action="decide" data-request="${esc(r.id)}" data-decision="approve" aria-label="Approve ${esc(r.applicant.name)}">Approve</button><button class="button secondary" data-action="decide" data-request="${esc(r.id)}" data-decision="pass" aria-label="Pass on ${esc(r.applicant.name)}">Pass</button></div></article>`).join(''):'<p class="quiet-empty">All caught up. No pending requests.</p>'}</section><div class="host-workspace"><div>${composerForm(hub.id,true)}<div class="community-section-heading"><h2>Your people <span>${members.length}</span></h2><a class="text-link" href="#chat/${encodeURIComponent(hub.slug)}">Open group chat →</a></div><div class="community-face-grid">${members.map(m=>communityPerson(hub,m,true)).join('')}</div></div><aside class="host-sidepanel"><p class="eyebrow">THE COMMUNITY</p><a class="button full-width" href="${feedLink(hub.slug)}">Open community ${arrow}</a><a class="button secondary full-width" href="#chat/${encodeURIComponent(hub.slug)}">Group chat ${arrow}</a><a class="text-link" href="${hubLink(hub.slug)}">Public page</a><button class="text-link" data-action="compose" data-hub="${esc(hub.id)}">Open photo composer</button><div class="host-qr-note"><h3>Let people find you.</h3><p>Place your host QR under your YouTube videos. It opens the sign-up flow, never an approval shortcut.</p><button class="text-link" data-action="host-qr" data-slug="${esc(hub.slug)}" ${hub.published?'':'disabled'}>View your host QR →</button></div><p class="small-note">Inviting someone directly is your approval. Their first trial starts when they accept; returning keeps the original deadline. Membership and optional support stay separate; only an enabled test checkout can open.</p></aside></div></section>`}
function postCard(post,isOwner){return `<article class="post"><div class="post-author"><span class="avatar-dot" aria-hidden="true">${esc((post.author?.name||'H').slice(0,1))}</span><div>${esc(post.author?.name||'Host')}<small>${esc(dateLabel(post.createdAt))}</small></div></div>${post.caption?`<p class="post-caption">${esc(post.caption)}</p>`:''}${photoUrl(post.photoUrl)?`<img class="feed-photo" src="${esc(photoUrl(post.photoUrl))}" alt="Photo shared with this circle" loading="lazy">`:''}<div class="post-footer"><span>For approved circle members</span>${isOwner?`<button data-action="delete-prompt" data-post="${esc(post.id)}">Remove post</button>`:''}</div></article>`}
function accessNote(access){if(!access)return '';if(access.source==='owner')return '<span>Host access</span>';if(access.source==='trial')return `<span>Seven-day trial · Ends ${esc(dateTimeLabel(access.trialEndsAt))}</span>`;if(access.source==='paid')return `<span>Paid access · Through ${esc(dateTimeLabel(access.paidUntil))}</span>`;return '<span>Current membership access is required</span>'}
function communityNav(hub,active){return `<nav class="community-tabs" aria-label="Community sections"><a ${active==='posts'?'aria-current="page"':''} href="${feedLink(hub.slug)}">Posts</a><a ${active==='chat'?'aria-current="page"':''} href="#chat/${encodeURIComponent(hub.slug)}">Community chat</a><a href="#my-qr/${encodeURIComponent(hub.slug)}">My shareable QR</a></nav>`}
function feedView(hub,posts,members,nextCursor,access){const owner=state.hub?.id===hub.id;return `<section class="page-shell"><a class="back-link" href="${owner?manageLink(hub.slug):hubLink(hub.slug)}">← ${owner?'Host dashboard':'Public page'}</a><div class="feed-header"><div><p class="eyebrow">${esc(hub.name)}</p><h1>${owner?'My Community':'Community'}</h1><div class="entitlement-note">${accessNote(access)}</div></div><div class="section-actions"><button class="button secondary" data-action="refresh">Refresh</button>${owner?`<button class="button" data-action="compose" data-hub="${esc(hub.id)}">Publish post ${arrow}</button>`:''}</div></div>${communityNav(hub,'posts')}<div class="circle-layout"><div id="posts-list">${posts.length?posts.map(p=>postCard(p,owner)).join(''):`<div class="empty-state"><h2>No posts yet.</h2><p>${owner?'Publish your first post for your approved community.':'Your host hasn’t published a post yet.'}</p></div>`}${nextCursor?`<div class="app-pagination"><button class="button secondary" data-action="more-posts" data-hub="${esc(hub.id)}" data-cursor="${esc(nextCursor)}">Load earlier posts</button></div>`:''}</div><aside class="sidebar"><h3>Your people</h3><div class="feed-members">${members.map(m=>`<a class="member-row" href="${m.id===state.user.id?'#profile':'#chat/'+encodeURIComponent(hub.slug)+'/'+encodeURIComponent(m.id)}">${avatar(m.photoUrl,m.name)}<div>${esc(m.name)}<small>${m.id===state.user.id?'Your profile':m.role==='owner'?'Message host':'Send a message'}</small></div></a>`).join('')}</div><p>Your email is not shown to other members.</p>${!owner?`<a class="button secondary full-width" href="#membership/${encodeURIComponent(hub.slug)}">Membership & optional support ${arrow}</a>`:''}${!owner?`<button class="text-link" data-action="leave-prompt" data-hub="${esc(hub.id)}" data-slug="${esc(hub.slug)}" data-revision="${esc(access?.membershipRevision||'')}">Leave this community</button>`:''}<p class="small-note">Membership controls future access. People may retain copies of content already viewed.</p></aside></div></section>`}
function entitlementView(hub,access){return `<section class="page-shell membership-expired"><p class="eyebrow">${esc(hub.name)}</p><h1>${access.source==='expired'?'Your trial has ended.':'This space is closed.'}</h1><p>${access.source==='expired'?'The seven-day trial has ended. Current confirmed paid access is needed to reopen community updates and chat.':'The host must approve your request before community updates or chat can open.'}</p><p class="small-note">An illustration cannot charge you or activate paid access. Only an enabled test checkout can open after approval, and its return URL never grants access.</p><div class="button-row"><a class="button secondary" href="${hubLink(hub.slug)}">View public page</a>${access.membershipStatus==='active'?`<a class="button" href="#membership/${encodeURIComponent(hub.slug)}">Review membership ${arrow}</a>`:''}</div></section>`}
function safeShareUrl(value){try{const u=new URL(value,location.origin);return u.origin===location.origin&&!u.username&&!u.password&&!u.search&&u.pathname==='/'&&/^#(?:hub\/[a-z0-9-]{3,40}|share\/[a-f0-9]{64})$/.test(u.hash)?u.href:''}catch{return ''}}
function qrMarkup(url,label){const safe=safeShareUrl(url);if(!safe)throw Error('The server returned an invalid community link.');return `<img class="qr-image" src="/api/wildhub-qr?url=${encodeURIComponent(safe)}" alt="${esc(label)}" width="240" height="240"><label class="qr-url">Shareable link<input readonly value="${esc(safe)}" aria-label="Shareable community link"></label><div class="qr-actions"><button class="button secondary" data-action="copy-link" data-url="${esc(safe)}">Copy link</button><a class="text-link" href="/api/wildhub-qr?url=${encodeURIComponent(safe)}" download="wild-hub-qr.svg">Download QR</a></div>`}
function qrView(hub,share){return `<section class="page-shell qr-shell"><ol class="qr-steps" aria-label="Joining steps"><li>Profile ready</li><li aria-current="step">Your QR</li><li>Meet the host</li><li>Approval & membership</li></ol><div class="qr-panel"><p class="eyebrow">YOUR OWN SHAREABLE QR</p><h1>Bring your people.</h1><p>Your code opens ${esc(hub.name)}’s public joining flow. It doesn’t reveal your identity or approve anyone.</p>${qrMarkup(share.url,'Your shareable QR for '+hub.name)}<div class="qr-context">${avatar(state.user.photoUrl,state.user.name)}<div><strong>${esc(state.user.name)}</strong><span>Sharing ${esc(hub.name)}</span></div></div><a class="button full-width" href="${hubLink(hub.slug)}">Continue to the host ${arrow}</a><p class="small-note">QR codes never bypass approval. You can share this code before your own request is approved. Access can still be declined or revoked.</p></div></section>`}
function qrPicker(hubs){return `<section class="page-shell qr-shell"><p class="eyebrow">YOUR PROFILE IS READY</p><h1>Which community?</h1><p>Choose a published host to make your own shareable QR. Then introduce yourself. Membership choices follow host approval.</p><div class="qr-hub-picker">${hubs.length?hubs.map(h=>`<a class="hub-tile" href="#my-qr/${encodeURIComponent(h.slug)}">${avatar(h.photoUrl,h.name)}<h2>${esc(h.name)}</h2><span>Make my QR ${arrow}</span></a>`).join(''):'<div class="empty-state"><h2>No published hosts yet.</h2><p>Create and publish a test hub to try the complete joining flow.</p><a class="button" href="#create">Create a hub ${arrow}</a></div>'}</div><a class="text-link" href="#home">Back home</a></section>`}
const planOptions=()=>[{id:'daily',label:'Daily',days:1,discount:0,price:1,period:'day'},{id:'monthly',label:'Monthly',days:30,discount:10,price:27,period:'month'},{id:'quarterly',label:'Quarterly',days:90,discount:20,price:72,period:'quarter'},{id:'annual',label:'Annual',days:365,discount:state.annualDiscount,price:365*(1-state.annualDiscount/100),period:'year'}];
const money=value=>'$'+value.toFixed(2).replace(/\.00$/,'');
function membershipGate(hub,access){return `<section class="page-shell membership-shell"><p class="eyebrow">${esc(hub.name)}</p><h1>Host approval comes first.</h1><p>${access?.membershipStatus==='pending'?'Your introduction is waiting for the host.':'You need a current approved membership before choosing a membership payment or optional contribution.'}</p><p>No checkout can open and no community content is shown before admission.</p><a class="button" href="${hubLink(hub.slug)}">View your request ${arrow}</a></section>`}
function serverPrice(p){return new Intl.NumberFormat(undefined,{style:'currency',currency:p.currency.toUpperCase()}).format(p.unitAmount/100)}
function billingPlan(p,selected,kind){return `<label class="membership-plan"><input type="radio" name="plan" value="${esc(p.planKey)}" ${selected===p.planKey?'checked':''} required><span class="plan-title">${esc(p.label)}</span><strong class="plan-price">${esc(serverPrice(p))}<small>${kind==='membership'?' / '+esc(p.intervalCount===3?'3 months':p.interval):' once'}</small></strong><span class="plan-discount">${kind==='membership'?'Recurring Stripe test subscription':'Optional one-time test contribution'}</span></label>`}
function membershipView(hub,access,config={enabled:false,membership:[],support:[]}){
 if(access?.source!=='owner'&&access?.membershipStatus!=='active')return membershipGate(hub,access);
 const enabled=config.enabled&&access.source!=='owner',plans=enabled?config.membership:[],selected=state.planChoices[hub.slug]?.id||plans[0]?.planKey||'monthly',supportPlans=enabled?config.support:[];
 return `<section class="page-shell membership-shell"><p class="eyebrow">${esc(hub.name)} · ${access.source==='owner'?'YOUR COMMUNITY':'HOST APPROVED'}</p><h1>${access.source==='owner'?'Your community is ready.':'You’re approved. Welcome in.'}</h1><div class="membership-entry"><h2>${access.source==='trial'?'Your seven-day trial is running.':access.source==='paid'?'Your membership is active.':access.source==='owner'?'Your host access is active.':'Your original trial has ended.'}</h2><p>${access.source==='trial'?`Your host approved you on ${esc(dateTimeLabel(access.trialStartedAt))}. Your trial ends ${esc(dateTimeLabel(access.trialEndsAt))}.`:access.source==='paid'?`Current access runs through ${esc(dateTimeLabel(access.paidUntil))}.`:access.source==='owner'?'You do not need to buy membership in your own community.':`The trial ended ${esc(dateTimeLabel(access.trialEndsAt))}. A confirmed current membership is required to reopen the exclusive page.`}</p>${access.allowed?`<a class="button" href="${feedLink(hub.slug)}">${access.source==='trial'?'Continue with my trial':'Open exclusive community'} ${arrow}</a>`:''}<p class="small-note">${access.source==='trial'?'No payment is needed to enter during this trial. It started at approval, not at this click. Continuing does not create a subscription or automatic charge.':'A choice or checkout return link never changes access by itself.'}</p></div>${deliveryNote(hub.id)}${config.status?`<p class="billing-notice">${config.status.checkout?'Server checkout status: '+esc(config.status.checkout.status)+'. Access is shown above from the membership server.':'No confirmed test checkout is recorded.'}${config.status.cancellation?' Cancellation status: '+esc(config.status.cancellation.status)+'.':''}</p>`:''}${access.source==='owner'?'<p class="billing-notice">The amounts below illustrate the member experience. Host checkout is unavailable.</p>':''}<div class="membership-choice-heading"><h2>Membership</h2><p>${plans.length?'Sandbox prices supplied by this isolated server. Use test payment details only.':'Illustrative prices using a $1/day starting point. Sandbox checkout is unavailable.'}</p></div><form class="app-form" id="membership-form" data-hub="${esc(hub.id)}" data-slug="${esc(hub.slug)}" data-revision="${esc(access.membershipRevision||'')}" data-checkout="${plans.length?'true':'false'}"><div class="membership-plans">${plans.length?plans.map(p=>billingPlan(p,selected,'membership')).join(''):planOptions().map(p=>`<label class="membership-plan"><input type="radio" name="plan" value="${p.id}" ${selected===p.id?'checked':''} required><span class="plan-title">${p.label}</span><strong class="plan-price">${money(p.price)}<small> / ${p.period}</small></strong><span class="plan-discount">${p.discount?p.discount+'% illustrative discount':'$1/day anchor'}</span><span class="plan-breakdown">${p.days}-day pricing assumption${p.discount?' × $1 × '+(100-p.discount)+'%':''}</span></label>`).join('')}</div>${!plans.length?`<label class="annual-illustration">Annual discount illustration<select name="annualDiscount" id="annual-discount"><option value="20" ${state.annualDiscount===20?'selected':''}>20% · $292/year</option><option value="25" ${state.annualDiscount===25?'selected':''}>25% · $273.75/year</option></select></label><div class="membership-summary"><p>USD illustration using 30 days/month, 90 days/quarter and 365 days/year. Actual calendar periods vary. Final prices, taxes, billing timing and processor-fee allocation are not configured.</p></div>`:''}<p class="small-note">The host receives the subscription payment with Wild Hub’s 10% platform share. Optional support is separate. ${plans.length?'Test checkout shows the recurring commitment before you confirm; no live charge is supported.':'This illustration cannot charge you or activate paid access.'}</p><p class="form-error" role="alert"></p><div class="membership-footer"><button class="button secondary" type="submit">${plans.length?'Prepare test membership checkout':'Preview this membership'} ${arrow}</button></div></form><section class="membership-support"><h2>Optional contribution</h2><p>A separate, one-time gesture to the creator. It is never required for approval, the trial or membership access.</p>${supportPlans.length?`<form class="app-form" id="support-form" data-hub="${esc(hub.id)}" data-slug="${esc(hub.slug)}" data-revision="${esc(access.membershipRevision||'')}"><div class="membership-plans">${supportPlans.map((p,i)=>billingPlan(p,i===0?p.planKey:'','support')).join('')}</div><p class="form-error" role="alert"></p><button class="button secondary" type="submit">Prepare optional test contribution ${arrow}</button></form>`:'<p class="billing-notice">Optional support checkout is unavailable. Nothing is charged.</p>'}</section><p class="small-note">No card details are entered in Wild Hub. Test checkout and approval are separate checks; a payment cannot restore removed access or restart a trial.</p><a class="text-link" href="${hubLink(hub.slug)}">View host page</a></section>`
}
function chatKey(hubId,peerId=''){return state.sessionGeneration+':'+(state.user?.id||'')+':'+hubId+':'+peerId}
function chatDraft(hubId,peerId=''){const key=chatKey(hubId,peerId);return state.chatDrafts[key]||(state.chatDrafts[key]={text:'',clientId:null})}
function messageCard(message){return `<article class="chat-message ${message.sender?.id===state.user?.id?'mine':''}"><div class="chat-meta"><strong>${esc(message.sender?.name||'Member')}</strong><time datetime="${esc(message.createdAt)}">${esc(new Date(message.createdAt).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))}</time></div><p class="chat-bubble">${esc(message.text)}</p></article>`}
function chatView(hub,members,result,peerId,access){const peer=peerId?members.find(m=>m.id===peerId):null;if(peerId&&!peer)throw Error('This person is no longer available in this community.');const title=peer?.name||'Community chat',draft=chatDraft(hub.id,peerId);return `<section class="page-shell"><div class="feed-header"><div><p class="eyebrow">${esc(hub.name)}</p><h1>${esc(title)}</h1><div class="entitlement-note">${accessNote(access)}</div></div><button class="button secondary" data-action="refresh">Refresh</button></div>${communityNav(hub,'chat')}<div class="chat-layout"><aside class="chat-directory"><a class="chat-person ${!peerId?'active':''}" href="#chat/${encodeURIComponent(hub.slug)}">${lock}<span>Everyone in the community<small>Group conversation</small></span></a><h2>Individual messages</h2>${members.filter(m=>m.id!==state.user.id).map(m=>`<a class="chat-person ${peerId===m.id?'active':''}" href="#chat/${encodeURIComponent(hub.slug)}/${encodeURIComponent(m.id)}">${avatar(m.photoUrl,m.name)}<span>${esc(m.name)}<small>${m.role==='owner'?'Host':'Member'}</small></span></a>`).join('')}</aside><section class="chat-thread" aria-label="${esc(title)}"><div class="chat-heading"><h2>${esc(title)}</h2><p>${peerId?'Visible to you and this person while both have current community access.':'Visible to everyone with current approved access to this community.'}</p></div>${result.nextCursor?`<button class="text-link chat-earlier" data-action="more-messages" data-hub="${esc(hub.id)}" data-peer="${esc(peerId||'')}" data-cursor="${esc(result.nextCursor)}">Load earlier messages</button>`:''}<div class="chat-messages" id="chat-messages" role="log" aria-live="polite">${result.messages?.length?[...result.messages].sort((a,b)=>a.createdAt.localeCompare(b.createdAt)||a.id.localeCompare(b.id)).map(messageCard).join(''):'<p class="chat-empty">Start the conversation.</p>'}</div><form class="app-form chat-form" id="chat-form" data-hub="${esc(hub.id)}" data-peer="${esc(peerId||'')}"><label class="chat-composer">Message ${esc(peerId?title:'the community')}<textarea name="text" maxlength="2000" placeholder="Write a message…" required>${esc(draft.text)}</textarea></label><p class="form-error" role="alert"></p><div class="composer-actions"><span class="small-note">Text only · Up to 2,000 characters</span><button class="button" type="submit" ${state.chatPending.has(chatKey(hub.id,peerId))?'disabled':''}>Send ${arrow}</button></div></form></section></div></section>`}
async function findHub(slug){return state.hub?.slug===slug?state.hub:state.memberships.find(m=>m.slug===slug)?{id:state.memberships.find(m=>m.slug===slug).hubId,slug,name:state.memberships.find(m=>m.slug===slug).name}:(await api('public_hub',undefined,{slug})).hub}
function inviteView(result,token){const i=result.invite;return `<section class="invitation-card"><p class="eyebrow">A PERSONAL INVITATION</p><h1>${esc(i.hostName)} invited you.</h1><p>Join ${esc(i.hubName)} to see posts shared with this approved circle.</p><p class="small-note">This invitation expires ${esc(dateLabel(i.expiresAt))} and is tied to the invited email address.</p>${!state.user?'<div class="button-row"><button class="button" data-action="join-signin">Sign in to view your invitation</button></div>':!complete()?'<div class="button-row"><button class="button" data-action="join-profile">Add your name and photo</button></div>':result.canAccept?`<form class="app-form" id="accept-form" data-token="${esc(token)}"><p>By accepting, you join this circle and share your name and photo with its members.</p><p class="form-error" role="alert"></p><div class="button-row"><button class="button" type="submit">Accept invitation ${arrow}</button><a class="button secondary" href="#home">Not now</a></div></form>`:'<p class="danger-note">Sign in with the email address this invitation was sent to. This account cannot accept it.</p>'}</section>`}
function privacyView(){return `<section class="page-shell privacy-copy"><h1>A private-circle test build.</h1><p>This app runs against a separate isolated test database. It does not use Duh Wild’s members, emails, content or billing. Checkout stays unavailable unless the isolated server explicitly enables Stripe test mode. No live payments are supported.</p><h2>What other people can see</h2><p>A published host page intentionally shows the host’s chosen name, photo, hub title and introduction. An applicant shares their name, photo and introduction with that host. People with current approved access can see eligible member names/photos, host posts and group messages. Individual messages are visible only to the two participants while both have current community access. Email addresses are not part of the member list or chat.</p><h2>Email and photos</h2><p>Email codes confirm access to an address, not a person’s identity or photo. ${providerMail()?'This isolated server sends real sign-in and notification emails only to permitted test recipients. A provider accepting a message does not prove inbox delivery.':'This local runner accepts only test-domain email and prints simulated mail to its terminal.'} Photos are decoded, resized and re-encoded by the server before storage.</p><h2>Access and retention</h2><p>Leaving, removal or blocking stops new protected reads. It cannot erase copies someone has already viewed or saved. Posts, images, group messages and individual message text are stored only in this isolated test database. ${state.runtime.environment==='isolated-test'?'Test data remains in the configured isolated store until its operator removes it.':'The default local runner uses memory, so stopping it clears that test data.'} An unsent draft stays only in the current browser tab and is cleared on sign-out or refresh.</p><h2>Before a public launch</h2><p>Final terms/privacy information, moderation operations, data retention and live billing still need release setup. This page explains the isolated test; it is not a finished public-service privacy policy.</p></section>`}
async function render(){
 const ticket=++state.epoch;
 stopCamera();
 clearTimeout(state.accessTimer);
 clearError();
 const raw=location.hash.slice(1)||'home',parts=raw.split('/'),view=parts[0];
 if(dialog.open)closeModal();
 app.innerHTML='<p class="loading">Opening your space…</p>';
 if(!state.runtime.known){app.innerHTML=runtimeUnavailable();return}
 try{
  let html,title;
  if(['signin','signup','verify','join-photo'].includes(view)){
   if(parts[1]){const context=decodeURIComponent(parts[1]);if(!/^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$/.test(context))throw Error('This host address is invalid.');state.acquisitionSlug=context;state.next='#my-qr/'+encodeURIComponent(context)}
   if(state.acquisitionSlug&&!parts[1])history.replaceState(null,'','#'+view+'/'+encodeURIComponent(state.acquisitionSlug));
  }
  if(view==='signin'||view==='signup'||view==='verify'){if(view==='verify'&&!state.email){navigate('#signin');return}html=authView(view)}
  else if(view==='join-photo'){if(!signedIn())return;if(complete()){navigate(state.next||'#home');return}if(!state.join.name||!state.join.agreed||state.join.email!==state.user.email){navigate('#signup');return}html=registrationPhotoView()}
  else if(view==='profile'){if(!signedIn())return;if(!complete()){navigate(registrationRoute());return}html=profileView()}
  else if(view==='create'){if(!profileReady())return;html=hubForm()}
  else if(view==='share'){const token=decodeURIComponent(parts[1]||'');if(!/^[a-f0-9]{64}$/.test(token))throw Error('This community QR link is invalid.');const result=await api('share_resolve',undefined,{token});if(ticket!==state.epoch)return;state.acquisitionSlug=result.frontDoor.slug;state.next='#my-qr/'+encodeURIComponent(state.acquisitionSlug);navigate(complete()?state.next:state.user?registrationRoute():'#signup');return}
  else if(view==='hub'){const slug=decodeURIComponent(parts[1]||''),result=await api('public_hub',undefined,{slug});if(ticket!==state.epoch)return;if(!state.user){state.acquisitionSlug=slug;state.next='#my-qr/'+encodeURIComponent(slug);navigate('#signup');return}if(!['owner','active','pending','passed','removed','blocked'].includes(result.relationship)&&complete()&&!state.qrSeen[slug]){state.acquisitionSlug=slug;navigate('#my-qr/'+encodeURIComponent(slug));return}html=publicView(result)}
  else if(view==='my-qr'){if(!profileReady())return;const slug=decodeURIComponent(parts[1]||state.acquisitionSlug||state.hub?.slug||'');if(!slug){html=qrPicker((await api('hubs')).hubs||[])}else{const hub=await findHub(slug),status=(await api('access_status',undefined,{hubId:hub.id})).access;if(['removed','blocked','left'].includes(status.membershipStatus)){delete state.shares[hub.id];throw Error('Your sharing link is unavailable because access to this community was removed.')}let share=state.shares[hub.id];if(share){try{await api('share_resolve',undefined,{token:share.token})}catch(error){if(ticket!==state.epoch)return;if(error.status!==404)throw error;delete state.shares[hub.id];share=null}}if(!share)share=(await api('share_create',{hubId:hub.id})).share;if(ticket!==state.epoch)return;if(!safeShareUrl(share?.url))throw Error('The server returned an invalid community QR.');state.shares[hub.id]=share;state.qrSeen[slug]=true;state.acquisitionSlug=slug;html=qrView(hub,share)}}
  else if(view==='membership'){if(!profileReady())return;const slug=decodeURIComponent(parts[1]||state.acquisitionSlug||state.hub?.slug||'');if(!slug){navigate('#dashboard');return}const hub=await findHub(slug),result=await api('access_status',undefined,{hubId:hub.id});if(ticket!==state.epoch)return;const access=result.access;let config=validatedBilling(null);if(access.membershipStatus==='active'&&access.source!=='owner')config=await billingConfig(hub.id);if(ticket!==state.epoch)return;state.billingConfigs[hub.id]={...config,revision:access.membershipRevision};scheduleAccessExpiry(access,ticket);html=membershipView(hub,access,config)}
  else if(view==='manage'){
   if(!profileReady())return;
   if(!state.hub||state.hub.slug!==decodeURIComponent(parts[1]||''))throw Error('Only the owner can manage this hub.');
   const hub=state.hub,[reqs,members]=await Promise.all([api('requests',undefined,{hubId:hub.id}),api('memberships',undefined,{hubId:hub.id,scope:'manage'})]);
   html=manageView(hub,reqs.requests||[],members.members||[]);title='My Community · '+hub.name+' · Wild Hub';
  }else if(view==='feed'||view==='chat'){
   if(!profileReady())return;
   const slug=decodeURIComponent(parts[1]||''),hub=await findHub(slug),access=(await api('access_status',undefined,{hubId:hub.id})).access;
   if(ticket!==state.epoch)return;scheduleAccessExpiry(access,ticket);
   if(!access.allowed)html=entitlementView(hub,access);
   else if(view==='feed'){const [posts,members]=await Promise.all([api('posts',undefined,{hubId:hub.id,limit:10}),api('memberships',undefined,{hubId:hub.id})]);html=feedView(hub,posts.posts||[],members.members||[],posts.nextCursor,access);title=(state.hub?.id===hub.id?'My Community':'Community')+' · '+hub.name+' · Wild Hub'}
   else{const peerId=decodeURIComponent(parts[2]||'');if(peerId===state.user.id){navigate('#chat/'+encodeURIComponent(slug));return}const [messages,members]=await Promise.all([api('chat_messages',undefined,{hubId:hub.id,peerId:peerId||undefined,limit:50}),api('memberships',undefined,{hubId:hub.id})]);if(ticket!==state.epoch)return;state.chatContext={hubId:hub.id,peerId};html=chatView(hub,members.members||[],messages,peerId,access)}
  }else if(view==='invite'){
   const token=decodeURIComponent(parts[1]||'');if(!/^[a-f0-9]{64}$/.test(token))throw Error('This invitation link is invalid.');
   html=inviteView(await api('invite_preview',undefined,{token}),token);
  }else if(view==='privacy')html=privacyView();
  else {if(view==='dashboard'&&state.user)await refreshMe();if(ticket!==state.epoch)return;html=homeView((await api('hubs')).hubs||[]);}
  if(ticket!==state.epoch)return;
  app.innerHTML=html;
  document.title=title||'Wild Hub · '+environmentLabel()+' build';
  window.scrollTo(0,0);app.focus({preventScroll:true});if(view==='verify')document.getElementById('signinCode')?.focus();
 }catch(error){
  if(ticket!==state.epoch)return;
  app.innerHTML=`<section class="server-error"><div class="gate-icon">${lock}</div><h1>${[401,402,403].includes(error.status)?'This space is closed.':'We couldn’t open that.'}</h1><p>${esc(error.message)}</p><div class="button-row"><button class="button" data-action="refresh">Try again</button><a class="button secondary" href="#home">Go home</a></div></section>`;
 }
}
async function preparePhoto(file,kind){
 if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPEG, PNG or WebP photo.');
 if(file.size>5*1024*1024)throw Error('Choose a photo smaller than 5 MiB.');
 const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Couldn’t read that photo.'));reader.readAsDataURL(file)});
 return new Promise((resolve,reject)=>{const image=new Image();image.onerror=()=>reject(Error('Couldn’t open that photo.'));image.onload=()=>{try{
  if(!image.width||!image.height||image.width*image.height>20000000)throw Error('Choose an image under 20 megapixels.');
  const canvas=document.createElement('canvas');const ctx=canvas.getContext('2d');
  if(kind==='profile'){canvas.width=canvas.height=320;const side=Math.min(image.width,image.height);ctx.drawImage(image,(image.width-side)/2,(image.height-side)/2,side,side,0,0,320,320)}
  else{const scale=Math.min(1,1280/Math.max(image.width,image.height));canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));ctx.drawImage(image,0,0,canvas.width,canvas.height)}
  const result=canvas.toDataURL('image/jpeg',.82);if(result.length>3*1024*1024)throw Error('This photo is too large. Choose a smaller one.');resolve(result);
 }catch(error){reject(error)}};image.src=data});
}
function compose(hubId){state.photos.post=null;modal('Publish post',composerForm(hubId))}
async function buttonAction(button){
 const action=button.dataset.action,originHash=location.hash,sessionGeneration=state.sessionGeneration;
 const stillHere=()=>button.isConnected&&location.hash===originHash&&state.sessionGeneration===sessionGeneration;
 if(action==='close'){closeModal();return}
 if(action==='refresh'){if(!state.runtime.known)await loadRuntime();await refreshMe();if(stillHere())await render();return}
 if(action==='join-signin'){state.next=location.hash;navigate('#signup');return}
 if(action==='join-profile'){state.next=location.hash;navigate(state.join.name&&state.join.agreed&&state.join.email===state.user?.email?'#join-photo':'#signup');return}
 if(action==='support'){if(!button.dataset.slug){notify('Optional support is available after host approval, from membership settings.');return}navigate('#membership/'+encodeURIComponent(button.dataset.slug));return}
 if(action==='camera'){await openRegistrationCamera();return}
 if(action==='capture'){await captureRegistrationPhoto();return}
 if(action==='compose'){compose(button.dataset.hub);return}
 if(action==='clear-composer'){state.communityCaption='';delete state.photos.communityPost;state.selection++;const form=document.getElementById('community-post-form');form?.reset();document.getElementById('communityPost-preview')?.replaceChildren();return}
 if(action==='host-qr'){const url=location.origin+'/#hub/'+encodeURIComponent(button.dataset.slug);modal('Your host QR',`<p>Place this below your YouTube videos or share it with people you want to reach. It opens registration, never immediate admission.</p>${qrMarkup(url,'Host QR for your public joining page')}<p class="small-note">The host still reviews every request. No membership, trial or charge is created by scanning.</p>`);return}
 if(action==='copy-link'){const url=safeShareUrl(button.dataset.url);if(!url)throw Error('This share link is invalid.');if(!navigator.clipboard?.writeText){button.closest('.qr-panel,.modal-content')?.querySelector('.qr-url input')?.select();notify('Select and copy the link shown above.');return}await navigator.clipboard.writeText(url);if(stillHere())notify('Community link copied.');return}
 if(action==='invite'){modal('Bring a friend along.',`<form class="app-form" id="invite-form" data-hub="${esc(button.dataset.hub)}"><label>Your friend’s email<input type="email" name="email" maxlength="254" placeholder="friend@example.test" required></label><p class="field-note">Only this email account can accept. ${providerMail()?'The isolated server emails its permitted test recipients.':'The local runner sends the link to its simulated terminal inbox, not real email.'}</p><p class="form-error" role="alert"></p><div class="button-row"><button type="submit" class="button">Create test invitation ${arrow}</button><button type="button" class="button secondary" data-action="close">Cancel</button></div></form>`);return}
 if(action==='remove-prompt'){modal('Manage circle access.',`<p>Removing ${esc(button.dataset.name)} stops future access to this circle’s posts and media. It cannot erase previously viewed copies.</p><form id="remove-form" class="app-form" data-hub="${esc(button.dataset.hub)}" data-user="${esc(button.dataset.user)}" data-revision="${esc(button.dataset.revision||'')}"><label class="checkbox-label"><input type="checkbox" name="block"><span>Also block new requests and invitations for this member in this hub.</span></label><p class="form-error" role="alert"></p><div class="button-row"><button type="submit" class="button danger-button secondary">Remove access</button><button type="button" class="button secondary" data-action="close">Cancel</button></div></form>`);return}
 if(action==='leave-prompt'){modal('Leave this circle?',`<p>You’ll lose access to new reads of its posts and member list. Returning requires the host’s approval.</p><form id="leave-form" class="app-form" data-hub="${esc(button.dataset.hub)}" data-slug="${esc(button.dataset.slug)}" data-revision="${esc(button.dataset.revision||'')}"><p class="form-error" role="alert"></p><div class="button-row"><button class="button danger-button secondary" type="submit">Leave circle</button><button type="button" class="button secondary" data-action="close">Stay</button></div></form>`);return}
 if(action==='delete-prompt'){modal('Remove this post?',`<p>It will no longer appear in the circle or be available through its photo link. Previously viewed copies may remain with members.</p><form class="app-form" id="delete-form" data-post="${esc(button.dataset.post)}"><p class="form-error" role="alert"></p><div class="button-row"><button class="button danger-button secondary" type="submit">Remove post</button><button type="button" class="button secondary" data-action="close">Cancel</button></div></form>`);return}
 if(button.disabled)return;button.disabled=true;
 try{
  if(action==='logout'){++state.epoch;state.sessionGeneration++;stopCamera();await api('logout',{});state.user=null;state.hub=null;state.memberships=[];state.requests=[];state.inbox={pendingRequests:0};state.notifications={};state.billingConfigs={};state.checkoutKeys={};state.photos={};state.selection++;state.email='';state.join={name:'',email:'',agreed:false};state.next='#home';state.acquisitionSlug='';state.shares={};state.qrSeen={};state.planChoices={};state.chatDrafts={};state.chatContext=null;state.chatPending.clear();state.communityCaption='';clearTimeout(state.accessTimer);stopCamera();renderNav();navigate('#home');notify('Signed out. This session was revoked.')}
  if(action==='withdraw'){await api('request_withdraw',{hubId:button.dataset.hub});if(stillHere())await render();notify('Request withdrawn. The host can no longer load its introduction photo.')}
  if(action==='resend'){await api('auth_start',{email:state.email});notify(providerMail()?'Another code was requested for your email.':'Another code was sent to the local test inbox.')}
  if(action==='decide'){const result=await api('request_decide',{requestId:button.dataset.request,decision:button.dataset.decision});if(!stillHere())return;if(result.notification&&state.hub)state.notifications[state.hub.id]=result.notification;await refreshMe();if(stillHere())await render();notify(button.dataset.decision==='approve'?'Member approved. Access follows their original trial or confirmed membership.':'Request passed.')}
  if(action==='more-messages'){const result=await api('chat_messages',undefined,{hubId:button.dataset.hub,peerId:button.dataset.peer||undefined,cursor:button.dataset.cursor,limit:50});if(stillHere()){const box=document.createElement('div');box.innerHTML=[...(result.messages||[])].sort((a,b)=>a.createdAt.localeCompare(b.createdAt)||a.id.localeCompare(b.id)).map(messageCard).join('');document.getElementById('chat-messages').prepend(box);if(result.nextCursor)button.dataset.cursor=result.nextCursor;else button.remove()}}
  if(action==='more-posts'){
   const result=await api('posts',undefined,{hubId:button.dataset.hub,cursor:button.dataset.cursor,limit:10});
   if(stillHere()){const box=document.createElement('div');box.innerHTML=(result.posts||[]).map(p=>postCard(p,state.hub?.id===button.dataset.hub)).join('');button.closest('.app-pagination').before(box);if(result.nextCursor)button.dataset.cursor=result.nextCursor;else button.closest('.app-pagination').remove()}
  }
 }finally{button.disabled=false}
}
document.addEventListener('click',event=>{const button=event.target.closest('button[data-action]');if(button){const hash=location.hash,generation=state.sessionGeneration,epoch=state.epoch;buttonAction(button).catch(error=>{if(button.isConnected&&epoch===state.epoch&&hash===location.hash&&generation===state.sessionGeneration&&!redactProtectedError(error))showError(error)})}});
document.addEventListener('change',async event=>{
 if(event.target.id==='annual-discount'){const form=event.target.closest('form'),selected=form.querySelector('[name=plan]:checked')?.value||'monthly';state.annualDiscount=Number(event.target.value)===20?20:25;state.planChoices[form.dataset.slug]={id:selected,label:planOptions().find(p=>p.id===selected)?.label};await render();return}
 const input=event.target;if(!input.dataset.photo)return;
 const kind=input.dataset.photo,ticket=++state.selection,form=input.closest('form');
 if(kind==='registration'){
  if(state.registrationPending&&state.registrationPending.generation===state.sessionGeneration)return;input.disabled=true;
  try{const value=await preparePhoto(input.files?.[0],'profile');if(ticket!==state.selection||!input.isConnected)return;stopCamera();const saved=await finishRegistration(value);if(saved===false&&ticket===state.selection&&input.isConnected)input.value=''}catch(error){if(ticket===state.selection&&input.isConnected){input.value='';document.getElementById('joinError').textContent=error.message}}finally{if(input.isConnected)input.disabled=false}
  return;
 }
 delete state.photos[kind];const submit=form.querySelector('button[type=submit]');submit.disabled=true;
 try{const value=await preparePhoto(input.files?.[0],kind);if(ticket!==state.selection||!input.isConnected)return;state.photos[kind]=value;document.getElementById(kind+'-preview').innerHTML=`<img class="${kind==='profile'?'photo-sample':'composition-preview'}" src="${esc(value)}" alt="Selected ${kind==='profile'?'profile':'post'} photo">`;form.querySelector('.form-error').textContent=''}catch(error){if(ticket===state.selection&&input.isConnected){input.value='';formError(form,error)}}finally{if(ticket===state.selection&&submit.isConnected&&!form.dataset.busy)submit.disabled=false}
});
document.addEventListener('submit',event=>{
 const form=event.target;if(!form.matches('.app-form'))return;event.preventDefault();
 if(form.id==='hub-form'){
  // Normalize before native validation so pasted uppercase or outer whitespace remains supported.
  const slug=form.elements.namedItem('slug');slug.value=slug.value.trim().toLowerCase();hubAddressError(form);
  if(!slug.validity.valid)hubAddressError(form,hubAddressHelp);
  if(!form.reportValidity()){[...form.elements].find(input=>input.willValidate&&!input.validity.valid)?.focus();return}
 }
 const data=new FormData(form);
 mutate(form,async(current,sameSession)=>{
  if(form.id==='signup-form'){const name=String(data.get('name')).trim(),email=String(data.get('email')).trim().toLowerCase();if(!name||!email)throw Error('Enter your first name and email.');if(data.get('agreed')!=='on')throw Error('Confirm you’re 18 or older and agree to the Terms and Privacy Policy.');state.join={name,email,agreed:true};state.email=email;state.authMode='signup';if(state.user?.verified&&state.user.email===email&&!complete()){if(current())navigate('#join-photo')}else{await api('auth_start',{email});if(current())navigate('#verify')}}
  else if(form.id==='signin-form'){state.authMode='signin';state.email=String(data.get('email')).trim().toLowerCase();await api('auth_start',{email:state.email});if(current())navigate('#verify')}
  else if(form.id==='verify-form'){if(!/^[0-9]{6}$/.test(String(data.get('code')).trim()))throw Error('Enter the six digit code from your email.');if(state.authVerifyPending)throw Error('Another sign-in is still finishing. Please wait.');state.authVerifyPending=true;state.authVerifyEmail=state.email;try{const result=await api('auth_verify',{email:state.authVerifyEmail,code:String(data.get('code')).trim()});if(!sameSession())return;const useResult=current();state.sessionGeneration++;state.epoch++;state.user=result.user;state.hub=result.hub;state.memberships=result.memberships||[];state.requests=result.requests||[];state.inbox=result.inbox||{pendingRequests:0};state.notifications={};syncNotifications();state.billingConfigs={};state.checkoutKeys={};renderNav();if(useResult){if(complete())navigate(state.next);else if(state.authMode==='signup')navigate('#join-photo');else{state.join.email=state.email;navigate('#signup');notify('There’s no page for that email yet. Start one here.')}}}finally{state.authVerifyPending=false;state.authVerifyEmail='';if(!current()&&/^#(?:signin|signup|verify)(?:\/|$)/.test(location.hash))await render()}}
  else if(form.id==='profile-form'){const selected=state.photos.profile,selection=state.selection;await api('profile_save',{name:String(data.get('name')).trim(),agreed:data.get('agreed')==='on',...(selected?{photoDataUrl:selected}:{})});if(state.selection===selection&&state.photos.profile===selected)delete state.photos.profile;await refreshMe();if(current())navigate(state.next==='#profile'?'#home':state.next);notify('Profile saved.')}
  else if(form.id==='hub-form'){await api('hub_save',{name:String(data.get('name')).trim(),slug:String(data.get('slug')).trim().toLowerCase(),about:String(data.get('about')).trim(),published:data.get('published')==='on',publishConsent:data.get('publishConsent')==='on'});await refreshMe();if(current())navigate(manageLink(state.hub.slug));notify('Hub saved in the isolated test database.')}
  else if(form.id==='membership-form'||form.id==='support-form'){
   const checkoutOperation=++state.checkoutGeneration,checkoutModal=state.modalGeneration,ownsCheckout=()=>current()&&state.checkoutGeneration===checkoutOperation&&state.modalGeneration===checkoutModal;
   try{
   const kind=form.id==='support-form'?'support':'membership',hubId=form.dataset.hub,revision=form.dataset.revision||null,access=(await api('access_status',undefined,{hubId})).access;if(!ownsCheckout())return;
   if(access.source!=='owner'&&(access.membershipStatus!=='active'||access.membershipRevision!==revision)){await render();throw Error('Your approval changed. Refresh before deciding again.')}
   if(kind==='membership'&&form.dataset.checkout!=='true'){const selected=planOptions().find(p=>p.id===data.get('plan'));if(!selected)throw Error('Choose a membership illustration.');state.planChoices[form.dataset.slug]={...selected};notify('Illustrative choice saved for this visit. No charge or subscription created.');return}
   const config=state.billingConfigs[hubId],planKey=String(data.get('plan')),chosen=config?.[kind]?.find(p=>p.planKey===planKey);if(access.source==='owner'||!config?.enabled||config.revision!==revision||!chosen)throw Error('Test checkout is unavailable for this choice.');
   const key=state.sessionGeneration+':'+hubId+':'+revision+':'+kind+':'+planKey;const requestKey=state.checkoutKeys[key]||(state.checkoutKeys[key]=crypto.randomUUID());
   const result=await billingApi('checkout',{hubId,kind,planKey,requestKey,expectedRevision:revision});if(!ownsCheckout())return;const url=safeCheckoutUrl(result.url);if(result.testMode!==true||!url)throw Error('The server did not return an allowed Stripe test checkout.');
   const latest=(await api('access_status',undefined,{hubId})).access;if(!ownsCheckout())return;if(latest.membershipStatus!=='active'||latest.membershipRevision!==revision){await render();return}
   modal(kind==='support'?'Optional test contribution':'Test membership checkout',`<p><strong>${esc(chosen.label)} · ${esc(serverPrice(chosen))}${kind==='membership'?' every '+esc(chosen.intervalCount===3?'3 months':chosen.interval):' once'}</strong></p><p>${kind==='support'?'This is a separate, optional one-time contribution. It never buys admission.':'This creates a recurring test subscription only if you confirm it in Stripe’s sandbox.'}</p><p>Use test payment details only. Community access changes only after the server confirms its status.</p><a class="button" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open Stripe test checkout ${arrow}</a><p class="small-note">After checkout, return here and check your access. A success URL is not proof of payment.</p><div class="button-row"><button class="button secondary" data-action="refresh">Check access</button><button class="text-link" data-action="close">Close</button></div>`);
   }catch(error){if(ownsCheckout())throw error}
  }
  else if(form.id==='chat-form'){const hubId=form.dataset.hub,peerId=form.dataset.peer||'',key=chatKey(hubId,peerId),draft=chatDraft(hubId,peerId),text=String(data.get('text')).trim();if(!text||text.length>2000)throw Error('Write a message of up to 2,000 characters.');if(state.chatPending.has(key))throw Error('Your previous message is still sending.');if(draft.text!==text){draft.text=text;draft.clientId=null}if(!draft.clientId)draft.clientId=crypto.randomUUID();const clientId=draft.clientId;state.chatPending.add(key);try{await api('chat_send',{hubId,...(peerId?{peerId}:{}),text,clientId});if(!sameSession())return;if(draft.text===text&&draft.clientId===clientId){draft.text='';draft.clientId=null}if(current())await render()}finally{state.chatPending.delete(key);if(sameSession()&&state.chatContext?.hubId===hubId&&state.chatContext.peerId===peerId){const submit=document.querySelector('#chat-form button[type=submit]');if(submit)submit.disabled=false}}}
  else if(form.id==='join-form'){const result=await api('request_join',{hubId:form.dataset.hubId,intro:String(data.get('intro')).trim()});if(!sameSession())return;if(result.notification)state.notifications[form.dataset.hubId]=result.notification;await refreshMe();if(current())await render();notify('Your introduction is saved in the host’s request list.')}
  else if(form.id==='invite-form'){await api('invite_create',{hubId:form.dataset.hub,email:String(data.get('email')).trim().toLowerCase()});if(current())closeModal();notify(providerMail()?'Test invitation created for the permitted recipient.':'Test invitation created. Its link is in the local terminal inbox.')}
  else if(form.id==='accept-form'){const result=await api('invite_accept',{token:form.dataset.token});await refreshMe();const membership=state.memberships.find(m=>m.hubId===result.membership.hubId);if(current())navigate(membership?'#membership/'+encodeURIComponent(membership.slug):'#home');notify('Invitation accepted. Access follows your original trial or confirmed membership.')}
  else if(form.id==='post-form'||form.id==='community-post-form'){const kind=form.id==='community-post-form'?'communityPost':'post',selected=state.photos[kind],selection=state.selection,caption=String(data.get('caption')).trim();if(!selected)throw Error('Choose a photo and wait for its preview.');await api('post_create',{hubId:form.dataset.hub,caption,photoDataUrl:selected});if(!sameSession())return;if(state.selection===selection&&state.photos[kind]===selected&&(kind!=='communityPost'||state.communityCaption.trim()===caption)){delete state.photos[kind];if(kind==='communityPost')state.communityCaption='';}if(current()){if(dialog.contains(form))closeModal();navigate(feedLink(state.hub.slug));notify('Post published')}}
  else if(form.id==='remove-form'){await api('membership_remove',{hubId:form.dataset.hub,userId:form.dataset.user,block:data.get('block')==='on',expectedRevision:form.dataset.revision||null});if(current()){closeModal();await render()}notify('Access removed.')}
  else if(form.id==='leave-form'){await api('leave',{hubId:form.dataset.hub,expectedRevision:form.dataset.revision||null});if(sameSession())delete state.shares[form.dataset.hub];await refreshMe();if(current()){closeModal();navigate(hubLink(form.dataset.slug))}notify('You left the circle.')}
  else if(form.id==='delete-form'){await api('post_delete',{postId:form.dataset.post});if(current()){closeModal();await render()}notify('Post removed.')}
 });
});
document.addEventListener('input',event=>{if(event.target.closest('#hub-form')&&event.target.name==='slug')hubAddressError(event.target.form);if(event.target.closest('#community-post-form')&&event.target.name==='caption')state.communityCaption=event.target.value;const form=event.target.closest('#chat-form');if(form&&event.target.name==='text'){const draft=chatDraft(form.dataset.hub,form.dataset.peer||'');if(draft.text!==event.target.value){draft.text=event.target.value;draft.clientId=null}}});
document.addEventListener('error',event=>{if(event.target.matches?.('.qr-image')){const note=document.createElement('p');note.className='form-error';note.textContent='The QR image could not load. Use the shareable link below, or refresh.';event.target.replaceWith(note)}},true);
dialog.addEventListener('cancel',event=>{event.preventDefault();closeModal()});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal()}});
window.addEventListener('hashchange',()=>{if(ready)render()});
window.addEventListener('pagehide',stopCamera);
window.addEventListener('pageshow',event=>{if(event.persisted&&ready)refreshMe().then(render).catch(showError)});
async function start(){try{await loadRuntime();await refreshMe();ready=true;await render()}catch(error){ready=true;if(!state.runtime.known){app.innerHTML=runtimeUnavailable();return}app.innerHTML=`<section class="server-error"><h1>The functional server isn’t ready.</h1><p>${esc(error.message)}</p><p class="small-note">This app requires a configured isolated test server. The separate published skin remains a design-only preview.</p><button class="button" data-action="refresh">Try again</button></section>`}}
start();
